package main

import (
  "os"

  "go.uber.org/zap"
)

func main() {
  logger, _ := zap.NewProduction()
  sugar := logger.Sugar()

  orders, err := loadOrders(os.Args[1])
  if err != nil {
    sugar.Errorf("load failed: %v", err)
    os.Exit(1)
  }
  for _, o := range orders {
    sugar.Infof("order %s imported amount=%d", o.ID, o.Amount)
  }
}

