func main() {
  logger, err := zap.NewProduction()
  if err != nil {
    panic(err)
  }
  defer logger.Sync()

  orders, err := loadOrders(os.Args[1])
  if err != nil {
    logger.Fatal("load failed", zap.String("path", os.Args[1]), zap.Error(err))
  }
  for _, o := range orders {
    logger.Info("order imported", zap.String("order_id", o.ID), zap.Int("amount", o.Amount))
  }
}

